// Guardamos 0x12345678 en cuatro bytes, eligiendo el orden a mano.
const buffer = new ArrayBuffer(4);
const vista = new DataView(buffer);
const bytes = new Uint8Array(buffer);
const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join(" ");

vista.setUint32(0, 0x12345678, false);   // false = big-endian
console.log("big-endian:    " + hex(bytes));

vista.setUint32(0, 0x12345678, true);    // true = little-endian
console.log("little-endian: " + hex(bytes));

// Y qué orden usa la máquina donde corrés esto
const probe = new Uint32Array([0x12345678]);
const enMemoria = hex(new Uint8Array(probe.buffer));
console.log("esta máquina guarda: " + enMemoria + (enMemoria.startsWith("78") ? "  (little-endian)" : "  (big-endian)"));
